                assert ref[a:b:st]==list(s[a:b:st]),(a,b,st,ref[a:b:st],list(s[a:b:st]))
            elif op=='get' and ref: j=random.randint(-n,n-1); assert ref[j]==s[j],(j,ref[j],s[j])
