            elif op=='del' and ref: j=random.randint(-n,n-1); del ref[j]; del s[j]
            elif op=='rev': ref.reverse(); s.reverse()
            elif op=='sort': ref.sort(); s.sort()
            elif op=='ops':
                o=set(random.sample(range(80),10))
                assert [x for x in ref if x in o]==list(s & o),'and'
                assert [x for x in ref if x not in o]==list(s - o),'sub'
                assert len(s|o)==len(set(ref)|o),'or'
