        except Exception as e: note(op,repr(e)[:200]); break
        if list(s)!=ref or len(s)!=len(ref): note(op+'-state',(ref[:10],list(s)[:10])); break
        if n and s.index(ref[-1] if ref else 0)!=len(ref)-1 if ref else False: note('idx2','')
print(bad)
