            if op=='add': o.add(k,v); pairs.append((k,v))
            elif op=='set': o[k]=v; pairs=[p for p in pairs if p[0]!=k]+[(k,v)] if k not in [p[0] for p in pairs] else [p for p in pairs if p[0]!=k] and [(kk,vv) for kk,vv in pairs if kk!=k] ; 
            elif op=='get': exp=[vv for kk,vv in pairs if kk==k]; assert o.get(k)==(exp[-1] if exp else None),('get',k,exp,o.get(k))
            elif op=='getlist': exp=[vv for kk,vv in pairs if kk==k]; assert o.getlist(k)==exp,(k,exp,o.getlist(k))
            elif op=='items': assert list(o.items(multi=True))==pairs,(pairs,list(o.items(multi=True)))
            elif op=='pickle': o2=pickle.loads(pickle.dumps(o)); assert list(o2.items(multi=True))==pairs,'pickle'
            elif op=='copy': assert list(o.copy().items(multi=True))==pairs and list(copy.deepcopy(o).items(multi=True))==pairs,'copy'
            elif op=='eq': assert o==OMD(pairs) and o==dict(o) ,'eq'; d=dict(o); 
            elif op=='popall':
                exp=[vv for kk,vv in pairs if kk==k]
                if exp: assert o.popall(k)==exp,'popall'; pairs=[p for p in pairs if p[0]!=k]
            elif op=='poplast':
                exp=[vv for kk,vv in pairs if kk==k]
                if exp:
                    r=o.poplast(k); assert r==exp[-1],('poplast',exp,r)
                    i=max(i for i,p in enumerate(pairs) if p[0]==k); del pairs[i]
            elif op=='todict': assert o.todict()=={kk:vv for kk,vv in pairs},'todict'
            elif op=='inv':
                inv=o.inverted(); assert list(inv.items(multi=True))==[(vv,kk) for kk,vv in pairs],'inv'
        except AssertionError as e: note(op,str(e)[:250])
        except Exception as e: note(op,repr(e)[:250]); break
        if op!='set' and dict(o)!={kk:vv for kk,vv in pairs}: note(op+'-state',(pairs,list(o.items(multi=True)))); break
        if op=='set': pairs=list(o.items(multi=True))
# OneToOne
for t in range(1000):
    d=OneToOne(); 
    for _ in range(20):
        k=random.choice(K); v=random.randint(0,5); op=random.choice(['set','del','pop','upd','setdef','popitem'])
        try:
            if op=='set': d[k]=v
            elif op=='del' and k in d: del d[k]
            elif op=='pop': d.pop(k,None)
            elif op=='upd': d.update({k:v})
            elif op=='setdef': d.setdefault(k,v)
            elif op=='popitem' and d: d.popitem()
        except Exception as e: note('oto-'+op,repr(e)); break
        if dict(d.inv)!={vv:kk for kk,vv in d.items()} or len(d)!=len(d.inv): note('oto-'+op,(dict(d),dict(d.inv))); break
print(bad)
